class Base {
public: virtual ~Base() = default;
};

class Derived : public Base {
public: ~Derived() override {}
};

// VTABLE Dispatch for Arrays
Base* poly_array = new Derived[5];

// Crucial: Virtual destructor allows 'delete[]'
// to look up derived destructors in the vtable
// and call them for every element (5 times).
delete[] poly_array;
// If ~Base() were not virtual, only Base destructors
// would run, leading to resource leaks/UB.
